"""Deterministic bundle renderer: selected items become one marked block.

One canonical representation for integration testing, not a
representation experiment. Rules:

- compiler-selected order is preserved exactly;
- every selected item renders exactly once, with its kind header;
- item bodies are verbatim bundle content (epistemic tags assigned by
  the Stage 6C canonical payload survive untouched; the renderer never
  paraphrases, compresses, or rewrites);
- nothing unselected can enter: the renderer sees only the bundle;
- no event history, digests, run codes, or ledger identifiers enter
  the model-facing text;
- stable delimiters mark the block for detection, idempotence, and
  reconciliation.
"""

from __future__ import annotations

import hashlib

from project_context.domain.bundles import ContextBundle
from project_context.runtime.model import BLOCK_CLOSE, BLOCK_OPEN, RenderedBlock, RenderPolicy


def _kind_header(kind: str) -> str:
    return f"[{kind.replace('_', ' ').upper()}]" if kind else "[ITEM]"


def render_bundle(bundle: ContextBundle, policy: RenderPolicy) -> RenderedBlock:
    """Render every selected item once, in bundle order. Pure."""
    sections = []
    for item in bundle.items:
        sections.append(f"{_kind_header(item.kind)}\n{item.content}")
    text = ""
    if sections:
        text = BLOCK_OPEN + "\n" + "\n\n".join(sections) + "\n" + BLOCK_CLOSE
    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
    return RenderedBlock(
        bundle_id=bundle.id,
        policy_id=policy.policy_id,
        text=text,
        item_count=len(bundle.items),
        digest=digest,
    )

{
  "name": "@project-context/opencode-runtime",
  "version": "0.1.0",
  "private": true,
  "description": "Explicit intervention runtime for Context Lab. Opt-in only; hook mutation contract UNVERIFIED (no live probe).",
  "type": "module",
  "engines": {
    "node": ">=22.18.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test tests/blocks.test.ts",
    "lint": "prettier --check .",
    "format": "prettier --write ."
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.16",
    "@types/node": "25.0.3",
    "prettier": "3.9.9",
    "typescript": "7.0.2"
  }
}

/**
 * Pure runtime-block helpers (no OpenCode dependency).
 *
 * The runtime block is one system text block delimited by stable
 * markers. Helpers detect, locate, and compare blocks so that
 * injection is idempotent and conflicts fail loudly instead of
 * stacking duplicate payloads.
 */

export const BLOCK_OPEN = "[CONTEXT RUNTIME]";
export const BLOCK_CLOSE = "[/CONTEXT RUNTIME]";

export function systemTexts(system: unknown): string[] {
  if (!Array.isArray(system)) return [];
  const out: string[] = [];
  for (const block of system) {
    if (
      typeof block === "object" &&
      block !== null &&
      typeof (block as Record<string, unknown>)["text"] === "string"
    ) {
      out.push((block as Record<string, unknown>)["text"] as string);
    }
  }
  return out;
}

/** Indices of system blocks carrying a runtime marker. */
export function findRuntimeBlocks(system: unknown): number[] {
  const hits: number[] = [];
  const texts = systemTexts(system);
  for (let i = 0; i < texts.length; i++) {
    if (texts[i].includes(BLOCK_OPEN)) hits.push(i);
  }
  return hits;
}

/** Index of the block byte-equal to the intended text, or -1. */
export function findExactBlock(system: unknown, text: string): number {
  const texts = systemTexts(system);
  for (let i = 0; i < texts.length; i++) {
    if (texts[i] === text) return i;
  }
  return -1;
}

/**
 * Context Lab intervention runtime for OpenCode V2 (pinned: 2.0.16).
 *
 * UNVERIFIED HOOK CONTRACT — READ BEFORE USE.
 *
 * The tested 6D surface is the Python synthetic harness
 * (`src/project_context/runtime/`, `fixtures/runtime-v1/`), which
 * proves render → inject → observe → reconcile structurally. This
 * TypeScript file prepares the live intervention shape but has NEVER
 * run against a real OpenCode session: whether assigning the assembled
 * `system` array inside `session.hook("context")` actually alters the
 * model request is UNCONFIRMED. Do not install this plugin for
 * ordinary work. Do not cite it as evidence. A single throwaway live
 * probe is the explicit next step if hook validation is required.
 *
 * Opt-in only: without PROJECT_CONTEXT_RUNTIME=inject this plugin
 * registers no hooks and changes nothing. The rendered block is read
 * from the file named by PROJECT_CONTEXT_RUNTIME_BLOCK.
 *
 * Fail-safe: the new system array is built first and assigned once;
 * any error leaves the event untouched (no partial writes). A
 * differing pre-existing runtime block refuses with an error instead
 * of stacking payloads; an identical block is a no-op.
 */

import { Plugin } from "@opencode/plugin";
import { findExactBlock, findRuntimeBlocks } from "./blocks.ts";
import { readFileSync } from "node:fs";

type SessionContextEvent = {
  sessionID: string;
  agent: string;
  model: { providerID: string; id: string; variant?: string };
  system: unknown;
  messages: unknown;
  tools: Record<string, { description: string; input: unknown }>;
  options: Record<string, unknown>;
};

type PluginContext = {
  app: { version: string };
  session: {
    hook: (
      name: "context",
      callback: (event: SessionContextEvent) => void | Promise<void>,
    ) => Promise<{ dispose: () => Promise<void> }>;
  };
};

function loadBlock(path: string | undefined): string {
  if (!path) throw new Error("PROJECT_CONTEXT_RUNTIME_BLOCK is not set");
  const text = readFileSync(path, "utf-8");
  if (!text.includes("[CONTEXT RUNTIME]")) {
    throw new Error("rendered block lacks runtime markers; refusing");
  }
  return text;
}

export default Plugin.define({
  id: "context-runtime-injection",
  async setup(ctx) {
    if (process.env["PROJECT_CONTEXT_RUNTIME"] !== "inject") return;
    const pluginCtx = ctx as unknown as PluginContext;
    const blockPath = process.env["PROJECT_CONTEXT_RUNTIME_BLOCK"];
    await pluginCtx.session.hook("context", (_event) => {
      const event = _event;
      const text = loadBlock(blockPath);
      if (!Array.isArray(event.system)) {
        throw new Error("unsupported request shape: system is not an array");
      }
      const marked = findRuntimeBlocks(event.system);
      if (marked.length > 0) {
        if (findExactBlock(event.system, text) >= 0) return; // idempotent
        throw new Error("injection_conflict: a different runtime block is present");
      }
      const next = [...event.system, { type: "text", text }];
      event.system = next;
    });
  },
});

/**
 * Runtime block helper tests (node:test, no test framework).
 * Run: npm test (requires devDependencies; hook shape unverified live).
 *
 * 1. marker scan finds marked blocks and ignores plain ones
 * 2. exact search matches byte-identical text only
 * 3. non-array system yields no blocks
 * 4. non-text blocks are skipped
 */

import { deepEqual, equal } from "node:assert/strict";
import { findExactBlock, findRuntimeBlocks, systemTexts } from "../src/blocks.ts";

{
  const system = [
    { type: "text", text: "You are a test assistant." },
    { type: "text", text: "[CONTEXT RUNTIME]\n[X]\nbody\n[/CONTEXT RUNTIME]" },
    { type: "text", text: "Follow project rules." },
  ];
  deepEqual(findRuntimeBlocks(system), [1]);
  equal(findExactBlock(system, "[CONTEXT RUNTIME]\n[X]\nbody\n[/CONTEXT RUNTIME]"), 1);
  equal(findExactBlock(system, "[CONTEXT RUNTIME]\n[Y]\nbody\n[/CONTEXT RUNTIME]"), -1);
}

{
  deepEqual(findRuntimeBlocks(null), []);
  deepEqual(findRuntimeBlocks("system"), []);
  deepEqual(systemTexts([{ type: "tool", id: 7 }, { type: "text", text: "hi" }]), ["hi"]);
  deepEqual(findRuntimeBlocks([]), []);
}

